INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_AGRIPPA_OCCULTA','primary text','Heinrich Cornelius Agrippa, De occulta philosophia libri tres (1533) — Bk II ch. 14, the Scale of Twelve (governance of the twelve zodiacal signs by twelve angels)','REUSE — primary source for the twelve zodiacal angels and the seven planetary scale'),
 ('SRC_DAVIDSON_ANGELS','secondary scholarship','Gustav Davidson, A Dictionary of Angels, Including the Fallen Angels (The Free Press / Macmillan, New York, 1967)','NEW — standard reference cross-attesting the names and zodiacal/planetary assignments of the zodiacal and planetary angels')
INSERT INTO _e VALUES
 ('ENT_ANGF_ZODIAC_12','The Twelve Zodiacal Angels','Collective','Collective','Renaissance Esoteric','astrology; angelology; zodiac','B','Closed, enumerable set of twelve angels governing the twelve signs of the zodiac per Agrippa, De occulta philosophia II.14 (the Scale of Twelve). A structural collective; member angels attested in Agrippa and catalogued by Davidson.'),
 ('ENT_ANGF_MALCHIDAEL','Malchidael (Aries)','Angel','Angel','Renaissance Esoteric','zodiac: Aries; fire','B','Angel governing Aries in Agrippa''s Scale of Twelve (also spelled Malahidael/Machidiel). Attested Agrippa II.14; Davidson, Dictionary of Angels.'),
 ('ENT_ANGF_ASMODEL','Asmodel (Taurus)','Angel','Angel','Renaissance Esoteric','zodiac: Taurus; earth','B','Angel governing Taurus in Agrippa''s Scale of Twelve. Attested Agrippa II.14; Davidson. Not to be confused with the demon Asmodeus.'),
 ('ENT_ANGF_AMBRIEL','Ambriel (Gemini)','Angel','Angel','Renaissance Esoteric','zodiac: Gemini; air','B','Angel governing Gemini in Agrippa''s Scale of Twelve. Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_MURIEL','Muriel (Cancer)','Angel','Angel','Renaissance Esoteric','zodiac: Cancer; water','B','Angel governing Cancer in Agrippa''s Scale of Twelve. Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_VERCHIEL','Verchiel (Leo)','Angel','Angel','Renaissance Esoteric','zodiac: Leo; fire','B','Angel governing Leo in Agrippa''s Scale of Twelve (also Verachiel). Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_HAMALIEL','Hamaliel (Virgo)','Angel','Angel','Renaissance Esoteric','zodiac: Virgo; earth','B','Angel governing Virgo in Agrippa''s Scale of Twelve. Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_ZURIEL','Zuriel (Libra)','Angel','Angel','Renaissance Esoteric','zodiac: Libra; air','B','Angel governing Libra in Agrippa''s Scale of Twelve. Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_BARBIEL','Barbiel (Scorpio)','Angel','Angel','Renaissance Esoteric','zodiac: Scorpio; water','B','Angel governing Scorpio in Agrippa''s Scale of Twelve (also a name among the planetary/lunar mansions in other lists). Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_ADVACHIEL','Advachiel (Adnachiel, Sagittarius)','Angel','Angel','Renaissance Esoteric','zodiac: Sagittarius; fire','B','Angel governing Sagittarius in Agrippa''s Scale of Twelve; spelled Advachiel by Agrippa, commonly Adnachiel in later angelologies. Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_HANAEL','Hanael (Capricorn)','Angel','Angel','Renaissance Esoteric','zodiac: Capricorn; earth','C','Angel governing Capricorn in Agrippa''s Scale of Twelve. HOMONYM: distinct from the archangel Haniel of Venus/Netzach (ENT_JM_HANIEL); the same name-stem is reused for a zodiacal governor here. Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_CAMBIEL','Cambiel (Aquarius)','Angel','Angel','Renaissance Esoteric','zodiac: Aquarius; air','B','Angel governing Aquarius in Agrippa''s Scale of Twelve (also Cambriel). Attested Agrippa II.14; Davidson.'),
 ('ENT_ANGF_BARCHIEL','Barchiel (Pisces)','Angel','Angel','Renaissance Esoteric','zodiac: Pisces; water','B','Angel governing Pisces in Agrippa''s Scale of Twelve (also Barakiel/Barchiel). Attested Agrippa II.14; Davidson.');
