 ('ENT_ANGF_ZODIAC_12','aligned_with','ENT_AST_DECANS','medium','The twelve zodiacal angels (one per sign) parallel and subdivide into the thirty-six decans (three per sign); functional alignment of the two zodiacal angelic schemes.'),
 ('ENT_SAINT_MICHAEL_CHR','member_of','ENT_SOL_PLANETARY_ANGELS','high','Michael is the Sun angel in the seven-planet grimoire scheme; wires the existing archangel into the existing (previously member-less) Seven Planetary Angels collective.'),
 ('ENT_SAINT_GABRIEL_CHR','member_of','ENT_SOL_PLANETARY_ANGELS','high','Gabriel is the Moon angel in the seven-planet grimoire scheme; wires the existing archangel into the collective.'),
 ('ENT_SAINT_RAPHAEL_CHR','member_of','ENT_SOL_PLANETARY_ANGELS','high','Raphael is the Mercury angel in the seven-planet grimoire scheme; wires the existing archangel into the collective.'),
 ('ENT_SOL_ANAEL','member_of','ENT_SOL_PLANETARY_ANGELS','high','Anael is the Venus angel; completes membership of the previously empty Seven Planetary Angels collective.'),
 ('ENT_SOL_SAMAEL_MARS','member_of','ENT_SOL_PLANETARY_ANGELS','high','Samael is the Mars angel; completes membership of the collective.'),
 ('ENT_SOL_SACHIEL','member_of','ENT_SOL_PLANETARY_ANGELS','high','Sachiel is the Jupiter angel; completes membership of the collective.'),
 ('ENT_SOL_CASSIEL','member_of','ENT_SOL_PLANETARY_ANGELS','high','Cassiel is the Saturn angel; completes membership of the collective.'),
 ('ENT_SAINT_MICHAEL_CHR','presides_over','ENT_SUN','high','Adds the missing solar rulership: Michael governs the Sun in the planetary-angel scheme (Agrippa, Scale of Seven).'),
 ('ENT_SAINT_GABRIEL_CHR','presides_over','ENT_MOON','high','Adds the missing lunar rulership: Gabriel governs the Moon in the planetary-angel scheme (Agrippa, Scale of Seven).'),
 ('ENT_SOL_ANAEL','presides_over','ENT_VENUS','high','Anael governs Venus in the planetary-angel scheme; wires the existing Venus angel to the existing Venus planet-category entity.');
